```python
def solution(input_data):
    lines = input_data.strip().split('\n')
    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transformers = []
    for i in range(1, K + 1):
        parts = lines[i].split()
        x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
        transformers.append((x, y, d, t, e))

    # dp[i][j] = minimum energy to reach cell (i,j)
    # Initialize with infinity, dp[0][0] = 0
    dp = [[float('inf')] * M for _ in range(N)]
    dp[0][0] = 0

    # For each transformer, precompute which cells (i,j) contain the transformer
    # Transformer is at (x,y) at time t, then moves periodically
    # At time τ, the transformer is at:
    # If τ < t: not in matrix
    # Else: let dt = τ - t, check position based on dt mod 4
    # Pattern: (x,y) -> (x+d,y-d) -> (x+d,y) -> (x,y+d) -> repeat

    # For each transformer, mark which (i,j, time) positions it occupies
    # time = i + j

    def get_transformer_pos(x, y, d, t, tau):
        if tau < t:
            return None
        dt = tau - t
        mod = dt % 4
        if mod == 0:
            return (x, y)
        elif mod == 1:
            return (x + d, y - d)
        elif mod == 2:
            return (x + d, y)
        else:  # mod == 3
            return (x, y + d)

    # Build transformer map: for each cell (i,j), list of energy values
    transformer_energy = [[[] for _ in range(M)] for _ in range(N)]

    for x, y, d, t, e in transformers:
        # The transformer can be at most at time N+M-2 (reaching bottom-right)
        # But also minimum at time t
        # For each possible cell within reasonable bounds
        for i in range(N):
            for j in range(M):
                tau = i + j
                if tau < t or tau > N + M - 2:
                    continue
                pos = get_transformer_pos(x, y, d, t, tau)
                if pos is not None and pos[0] == i and pos[1] == j:
                    transformer_energy[i][j].append(e)

    # Add transformer energies to cells
    for i in range(N):
        for j in range(M):
            if transformer_energy[i][j]:
                dp[i][j] += sum(transformer_energy[i][j])

    # Dynamic programming: minimum energy to reach each cell
    for i in range(N):
        for j in range(M):
            if i == 0 and j == 0:
                continue
            # Can come from:
            # (i-1, j) - moving down (from previous row)
            # (i, j-1) - moving right (from previous column)
            if i > 0 and dp[i-1][j] != float('inf'):
                dp[i][j] = min(dp[i][j], dp[i-1][j])
            if j > 0 and dp[i][j-1] != float('inf'):
                dp[i][j] = min(dp[i][j], dp[i][j-1])

    result = dp[N-1][M-1]
    return str(result)


