def bfs(start, n, adj):
    """BFS to find shortest path from start node to all other nodes"""
    dist = [-1] * (n + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
