def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    p_set = set(p)
    index = {x: i for i, x in enumerate(p)}

    adj = [set() for _ in range(n)]

    for i, x in enumerate(p):
        y = a - x
        if y in p_set:
            j = index[y]
            if j != i:
                adj[i].add(j)
            else:
                adj[i].add(i)
        y = b - x
        if y in p_set:
            j = index[y]
            if j != i:
                adj[i].add(j)
            else:
                adj[i].add(i)

    result = [0] * n
    visited = [False] * n
    possible = True

    def dfs(node, current_set):
        nonlocal possible
        visited[node] = True
        result[node] = current_set

        for neighbor in adj[node]:
            if not visited[neighbor]:
                if dfs(neighbor, current_set):
                    return True
            elif result[neighbor] != current_set:
                return False
        return True

    for i in range(n):
        if not visited[i]:
            if dfs(i, 0):
                continue
            else:
                possible = False
                break

    if not possible:
        return "NO"

    output = ' '.join(str(result[i]) for i in range(n))
    return f"YES\n{output} \n"
