    """Find vertices adjacent to vertex in the triangulation with polygon edges"""
    neighbors = [vertex - 1, (vertex) % n + 1]  # polygon edges
    for i in range(1, n + 1):
        if i != vertex:
            d = tuple(sorted((vertex, i)))
            if d in diag_set:
                if i not in neighbors:
