    return sorted(set(neighbors))


def is_valid_triangle(n, diag_set, u, v, w):
    """Check if (u,v,w) forms a triangle in the triangulation"""
    for x, y in [[u, v], [v, w], [w, u]]:
        edge = tuple(sorted((x, y)))
        if not (edge in diag_set or is_polygon_edge(x, y, n)):
            return False
    return True


