    return abs(u - v) == 1 or abs(u - v) == n - 1


def find_flip_diagonal(n, diag_set, diag):
    """Find the diagonal to flip when we flip diag"""
    a, b = diag

    # Find the two triangles adjacent to this diagonal
    # They share (a,b), and the other two vertices define the flip diagonal

    neighbors_a = get_vertices_neighbors(n, diag_set, a)
    neighbors_b = get_vertices_neighbors(n, diag_set, b)

    # The flip diagonal connects the vertex after a (excluding b) to the vertex before b (excluding a)
    # In simpler terms: find vertices that make a with and b form triangles

    for ca in neighbors_a:
        if ca == b:
            continue
        for cb in neighbors_b:
            if cb == a:
                continue
            # Check if (ca, cb) would form valid triangles
            if is_valid_triangle(n, diag_set, a, b, ca):
                if is_valid_triangle(n, diag_set, a, b, cb):
                    flip = tuple(sorted((ca, cb)))
                    if flip not in diag_set:
