    for i in range(n):
        for b in range(MAX_BAL):
            if not dp[i][b]:
                continue

            cur = b - OFFSET  # Actual balance

            # Determine possible characters for position i
            if s[i] == '?':
                options = ['D', 'L', 'W']
            else:
                options = [s[i]]

            for c in options:
                if c == 'W':
                    nb = cur + 1
                elif c == 'L':
                    nb = cur - 1
                else:
                    nb = cur

                # Check constraints
                if i + 1 < n:
                    # Before final position: abs(balance) must be < k
                    if abs(nb) >= k:
                        continue
                else:
                    # At final position: abs(balance) must equal k
                    if abs(nb) != k:
                        continue

                nb_idx = nb + OFFSET
                if not dp[i+1][nb_idx]:
                    dp[i+1][nb_idx] = True
                    best[i][b] = c

    # Find any valid final state
    found = False
    start_b = None
    for b in range(MAX_BAL):
        if dp[n][b]:
            found = True
            start_b = b
            break

    if not found:
        return "NO\n"

    # Backtrack to reconstruct the sequence
    res = []
    b = start_b

    for i in range(n):
        c = best[i][b]
        res.append(c)

        if c == 'W':
            b -= 1
        elif c == 'L':
            b += 1
        # For 'D', balance doesn't change

    return ''.join(res[::-1]) + '\n'
```

Looking at this problem, I need to:

1. Find if there's a cycle through each starting vertex with total length L
2. Check if odometer starting at s can show 0 at the end, meaning: (s + L) % t = 0, or L ≡ (-s) mod t

The key insight is that if a vertex v has cycles with lengths that are multiples of some G_v (the GCD of all fundamental cycle lengths through v), then we can achieve any distance D ≡ 0 mod G_v through v.

For the odometer to show 0, we need: (s + L) % t = 0, which means we need a cycle distance L where (s + L) is divisible by t. Since L can be any value ≡ 0 (mod G_v) by taking multiples of G_v, we need (s) % gcd(G_v, t) == 0.

Let me code this solution:

```python
import sys
sys.setrecursionlimit(500000)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    idx = 1
    for _ in range(m):
        a, b, w = map(int, lines[idx].split())
        idx += 1
        adj[a].append((b, w))
        adj[b].append((a, w))

    idx = m + 1
    q_val = int(lines[idx])
    idx += 1

    d = [0] * (n + 1)
    g = [0] * (n + 1)
    visited = [False] * (n + 1)

    def dfs(u, p, dist):
        visited[u] = True
        d[u] = dist

        for v, w in adj[u]:
            if v == p:
                continue
            if visited[v]:
                # Back-edge: u -> v forms a cycle
                cycle = abs(d[u] - d[v] + w)
                g[u] = gcd(g[u], cycle)
            else:
                dfs(v, u, dist + w)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1, 0)

    results = []
    for i in range(q_val):
        v, s, t = map(int, lines[idx + i * 3 : idx + (i + 1) * 3])

        if s == 0:
            results.append("YES")
        elif g[v] == 0:
            results.append("NO")
        else:
            if (t - s) % g[v] == 0:
                results.append("YES")
            else:
                results.append("NO")

    return '\n'.join(results)

