def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0"

    n, h, m = map(int, lines[0].split())
    restrictions = []

    # Parse exactly m restriction lines
    for i in range(1, m + 1):
        if i < len(lines):
            parts = list(map(int, lines[i].split()))
            if len(parts) >= 4:
                l, r, x, c = parts[0], parts[1], parts[2], parts[3]
                restrictions.append((l, r, x, c))

    # Compute max allowed height for each position (considering all restrictions)
    max_at_pos = [h] * n
    for l, r, x, c in restrictions:
        for i in range(l - 1, r):
            max_at_pos[i] = min(max_at_pos[i], x)

    max_profit = float('-inf')
    current_heights = [0] * n

    def compute_penalty(heights):
        penalty = 0
        for l, r, x, c in restrictions:
            max_h = max(heights[l-1:r])
            if max_h > x:
                penalty += c
        return penalty

    def backtrack(idx, current_sum_sq):
        nonlocal max_profit

        if idx == n:
            profit = current_sum_sq - compute_penalty(current_heights)
            if profit > max_profit:
