def solution(input_str):
    data = input_str.strip().split()
    if not data:
        return "-1\n"

    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    valid_m = []

    for m in range(1, n + 1):
        if is_valid(m, a):
            valid_m.append(m)

    if not valid_m:
        return "-1\n"
    else:
