def is_valid(m, a):
    n = len(a)
    idx = 0

    for _ in range(m):
        if idx >= n:
            return False

        # Each partition must start with 1
        if a[idx] != 1:
            return False

        idx += 1

        # Try to match consecutive powers of 2
        expected = 2
        while idx < n:
            val = a[idx]
            if val == expected:
                idx += 1
                expected *= 2
            else:
                # This element is the remainder r for this partition
                idx += 1
                break

    return idx == n

